<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Media;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;class MediaController extends Controller{public function index(){return view('admin.media.index',['items'=>Media::latest()->paginate(30)]);}public function store(Request $r){$r->validate(['files'=>'required','files.*'=>'file|max:15360|mimes:jpg,jpeg,png,webp,avif,pdf']);foreach($r->file('files') as $file){$path=$file->store('media/'.date('Y/m'),'public');Media::create(['name'=>$file->getClientOriginalName(),'file'=>$path,'mime'=>$file->getMimeType(),'size'=>$file->getSize(),'collection'=>$r->input('collection','general')]);}return back()->with('ok','Файлы загружены');}public function destroy(Media $medium){if($medium->galleries()->exists())return back()->withErrors(['media'=>'Файл используется в фотоальбоме. Сначала уберите его из альбома.']);Storage::disk('public')->delete($medium->file);$medium->delete();return back();}}